module logic;
use model {Summary,Job};
use util {reverse};
record HasState {pending:List<I64>,found:Bool}
record AllState {pending:List<I64>,completed:List<I64>,all:Bool}
record Candidate {found:Bool,id:I64,cost:I64}
record ScanState {pending:List<Job>,completed:List<I64>,budget:I64,best:Candidate}
record RunState {jobs:List<Job>,completed:List<I64>,order:List<I64>,spent:I64,budget:I64,active:Bool}

fn has(items:List<I64>,value:I64)->Bool {
 let state=fold(i in List::length(items), state:HasState=HasState {pending:items,found:false}) {
  HasState {pending:List::tail(state.pending),found:state.found || List::head(state.pending)==value}
 };
 state.found
}

fn deps_done(deps:List<I64>,completed:List<I64>)->Bool {
 let state=fold(i in List::length(deps), state:AllState=AllState {pending:deps,completed:completed,all:true}) {
  AllState {pending:List::tail(state.pending),completed:state.completed,all:state.all && has(state.completed,List::head(state.pending))}
 };
 state.all
}

fn scan(jobs:List<Job>,completed:List<I64>,budget:I64)->Candidate {
 let state=fold(i in List::length(jobs), state:ScanState=ScanState {pending:jobs,completed:completed,budget:budget,best:Candidate {found:false,id:0,cost:0}}) {
  let job=List::head(state.pending);
  let eligible=!has(state.completed,job.id) && deps_done(job.deps,state.completed) && job.cost<=state.budget;
  let better=eligible && (!state.best.found || job.id<state.best.id);
  ScanState {pending:List::tail(state.pending),completed:state.completed,budget:state.budget,best:if better {Candidate {found:true,id:job.id,cost:job.cost}} else {state.best}}
 };
 state.best
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let final=while(state:RunState=RunState {jobs:jobs,completed:List::empty<I64>(),order:List::empty<I64>(),spent:0,budget:budget,active:true}; state.active) {
  let candidate=scan(state.jobs,state.completed,state.budget-state.spent);
  if candidate.found {
   RunState {jobs:state.jobs,completed:List::prepend(candidate.id,state.completed),order:List::prepend(candidate.id,state.order),spent:state.spent+candidate.cost,budget:state.budget,active:true}
  } else {
   RunState {jobs:state.jobs,completed:state.completed,order:state.order,spent:state.spent,budget:state.budget,active:false}
  }
 };
 Summary {order:reverse(final.order),spent:final.spent,blocked:List::length(jobs)-List::length(final.completed)}
}

